size_t i;
size_t worst_idx = 0;
size_t used_count;
int valid = 1;
int rejected = 0;
double full_worst = 0.0;
double reduced_worst;
double angle;
adcs_status_t st;
adcs_quat_t q_full;
adcs_quat_t q_used;
adcs_mat3_t dcm;
adcs_vec3_t body_n, in_n, pred;
adcs_vec3_t rb[4], ri[4];
double rw[4];

/* config validation */
if ((qr_config.allow_outlier_reject != 0) && (qr_config.allow_outlier_reject != 1)) valid = 0;
if ((qr_input.enable != 0) && (qr_input.enable != 1)) valid = 0;
if (!isfinite(qr_config.residual_limit_rad) || (qr_config.residual_limit_rad < 0.0) ||
    (qr_config.residual_limit_rad > ADCS_PI)) valid = 0;
if ((qr_config.required_good < 1U) || (qr_config.required_good > 20U)) valid = 0;
if ((qr_input.count < 2U) || (qr_input.count > 4U)) valid = 0;
if ((qr_input.body == NULL) || (qr_input.inertial == NULL) || (qr_input.weights == NULL)) valid = 0;

if (valid) {
    for (i = 0; i < qr_input.count; i++) {
        if ((!adcs_is_finite_vec3(&qr_input.body[i])) ||
            (!adcs_is_finite_vec3(&qr_input.inertial[i])) ||
            (!isfinite(qr_input.weights[i])) || (qr_input.weights[i] <= 0.0)) {
            valid = 0;
        }
    }
}

/* enable == 0 */
if (valid && (qr_input.enable == 0)) {
    qr_state.mode = QR_OFF;
    qr_state.good = 0U;
    qr_output.mode = QR_OFF;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0U;
    qr_output.rejected_outlier = 0;
    return;
}

/* invalid */
if (!valid) {
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = qr_input.count;
    qr_output.rejected_outlier = 0;
    return;
}

/* full-set quest */
st = adcs_quest(qr_input.body, qr_input.inertial, qr_input.weights, qr_input.count, &q_full);
if (st != ADCS_OK) {
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = qr_input.count;
    qr_output.rejected_outlier = 0;
    return;
}

/* full-set worst residual */
dcm = adcs_quat_to_dcm_bi(&q_full);
for (i = 0; i < qr_input.count; i++) {
    pred = adcs_mat3_mul_vec(&dcm, &qr_input.inertial[i]);
    if (adcs_vec3_normalize(&pred, ADCS_EPS_NORM, &pred) != ADCS_OK) {
        valid = 0;
        break;
    }
    if (adcs_vec3_normalize(&qr_input.body[i], ADCS_EPS_NORM, &body_n) != ADCS_OK) {
        valid = 0;
        break;
    }
    angle = acos(ADCS_CLAMP(adcs_vec3_dot(&pred, &body_n), -1.0, 1.0));
    if ((i == 0) || (angle > full_worst)) {
        full_worst = angle;
        worst_idx = i;
    }
}
if (!valid) {
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = qr_input.count;
    qr_output.rejected_outlier = 0;
    return;
}

/* initial accepted result = full set */
q_used = q_full;
used_count = qr_input.count;
rejected = 0;
qr_output.worst_residual_rad = full_worst;

/* retry once with single outlier removed */
if ((full_worst > qr_config.residual_limit_rad) && (qr_config.allow_outlier_reject != 0) &&
    (qr_input.count > 2U)) {
    size_t n = 0;
    for (i = 0; i < qr_input.count; i++) {
        if (i == worst_idx) continue;
        rb[n] = qr_input.body[i];
        ri[n] = qr_input.inertial[i];
        rw[n] = qr_input.weights[i];
        n++;
    }
    if ((n == qr_input.count - 1U) && (n >= 2U)) {
        adcs_quat_t q_red;
        st = adcs_quest(rb, ri, rw, n, &q_red);
        if (st == ADCS_OK) {
            adcs_mat3_t dcmr = adcs_quat_to_dcm_bi(&q_red);
            double red_ok = 1.0;
            reduced_worst = 0.0;
            for (i = 0; i < n; i++) {
                pred = adcs_mat3_mul_vec(&dcmr, &ri[i]);
                if (adcs_vec3_normalize(&pred, ADCS_EPS_NORM, &pred) != ADCS_OK) {
                    red_ok = 0.0;
                    break;
                }
                if (adcs_vec3_normalize(&rb[i], ADCS_EPS_NORM, &in_n) != ADCS_OK) {
                    red_ok = 0.0;
                    break;
                }
                angle = acos(ADCS_CLAMP(adcs_vec3_dot(&pred, &in_n), -1.0, 1.0));
                if ((i == 0) || (angle > reduced_worst)) reduced_worst = angle;
            }
            if ((red_ok > 0.5) && (reduced_worst <= qr_config.residual_limit_rad)) {
                q_used = q_red;
                used_count = n;
                rejected = 1;
                qr_output.worst_residual_rad = reduced_worst;
            }
        }
    }
}

/* decision table */
if (qr_output.worst_residual_rad <= qr_config.residual_limit_rad) {
    qr_state.good = qr_state.good + 1U;
    if (qr_state.good >= qr_config.required_good) {
        qr_state.mode = QR_READY;
    } else {
        qr_state.mode = QR_MONITOR;
    }
} else {
    qr_state.good = 0U;
    qr_state.mode = QR_MONITOR;
}

qr_output.mode = qr_state.mode;
qr_output.good = qr_state.good;
qr_output.q_bi = q_used;
qr_output.used_count = (unint32)used_count;
qr_output.rejected_outlier = rejected;

